bool ioc_profile_match_0(const Indicator&i,const std::string&v){auto x=core::lower(core::trim(v));if(i.type==Type::Domain)return core::norm_domain(x)==i.norm;if(i.type==Type::URL)return core::norm_url(x)==i.norm;if(i.type==Type::Hash)return x==i.norm;auto ip=core::parse_ipv4(x);if(ip&&i.type==Type::IPv4)return ip.value().v==i.ip.v;if(ip&&i.type==Type::CIDR)return i.cidr.contains(ip.value());return false;}
core::Severity ioc_profile_severity_0(const Indicator&i){if(i.list==List::Block)return core::Severity::High;if(i.list==List::Allow)return core::Severity::Info;return i.sev;}
